int write_to_task_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_REGISTER_OFFSET && addr < (PSW_REGISTER_OFFSET + sizeof(psw_t))) {
        // Processor status word register
        psw_t *psw = (psw_t *)((char *)child + addr);
        if (sizeof(psw_t) != sizeof(data)) {
            return -EINVAL;
        }
        *psw = data;
        return 0;
    } else if (addr >= GPRS_REGISTER_OFFSET && addr < (GPRS_REGISTER_OFFSET + sizeof(gprs_t))) {
        // General purpose registers
        gprs_t *gprs = (gprs_t *)((char *)child + addr);
        if (sizeof(gprs_t) != sizeof(data) && sizeof(gprs_t) != 8) {
            return -EINVAL;
        }
        if (sizeof(gprs_t) == 8 && (addr % 8) == 4) {
            // Prevent writing to padding holes
            return -EINVAL;
        }
        *gprs = data;
        return 0;
    } else if (addr >= FPRS_REGISTER_OFFSET && addr < (FPRS_REGISTER_OFFSET + sizeof(fprs_t))) {
        // Floating-point registers
        fprs_t *fprs = (fprs_t *)((char *)child + addr);
        if (sizeof(fprs_t) != sizeof(data)) {
            return -EINVAL;
        }
        *fprs = data;
        return 0;
    } else if (addr >= PER_INFO_OFFSET && addr < (PER_INFO_OFFSET + sizeof(per_info_t))) {
        // per_info structure
        per_info_t *per_info = (per_info_t *)((char *)child + addr);
        if (sizeof(per_info_t) != sizeof(data)) {
            return -EINVAL;
        }
        *per_info = data;
        return 0;
    } else {
        // Invalid address
        return -EINVAL;
    }
}

int write_child_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_ADDR_START && addr <= PSW_ADDR_END) {
        if (addr == PSW_ADDR) {
            if ((data & PSW_VALID_MASK) != data)
                return -EINVAL;
            child->thread.psw = data;
        } else if (addr >= GPRS_ADDR_START && addr <= GPRS_ADDR_END) {
            int reg_index = addr - GPRS_ADDR_START;
            if (reg_index >= 0 && reg_index < NUM_GPRS) {
                if ((data & GPR_VALID_MASK) != data)
                    return -EINVAL;
                child->thread.gprs[reg_index] = data;
            } else {
                return -EINVAL;
            }
        } else if (addr >= FPRS_ADDR_START && addr <= FPRS_ADDR_END) {
            int reg_index = addr - FPRS_ADDR_START;
            if (reg_index >= 0 && reg_index < NUM_FPRS) {
                if ((data & FPR_VALID_MASK) != data)
                    return -EINVAL;
                child->thread.fprs[reg_index] = data;
            } else {
                return -EINVAL;
            }
        } else if (addr == PER_INFO_ADDR) {
            if ((data & PER_INFO_VALID_MASK) != data)
                return -EINVAL;
            child->thread.per_info = data;
        } else {
            return -EINVAL;
        }
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if ((addr >= 0 && addr < 16) || (addr >= 32 && addr < 48)) {
        if (addr < 16) {
            /* Handle general purpose register (gprs) */
            if (data > 0xFFFFFFFF) {
                return -EINVAL;
            }
            child->thread.gprs[addr] = data;
        } else {
            /* Handle 64-bit register (psw) */
            if (data > 0xFFFFFFFFFFFFFFFF) {
                return -EINVAL;
            }
            child->thread.psw = data;
        }
    } else if (addr >= 48 && addr < 64) {
        /* Handle floating-point registers */
        if (data > 0xFFFFFFFFFFFFFFFF) {
            return -EINVAL;
        }
        child->thread.fprs[addr - 48] = data;
    } else if (addr == 64) {
        /* Handle per_info structure */
        if (data > 0xFFFFFFFF) {
            return -EINVAL;
        }
        child->thread.per_info = data;
    } else {
        /* Address not in a valid register range */
        return -EINVAL;
    }

    return 0;
}

int write_child_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_ADDRESS_MIN && addr <= PSW_ADDRESS_MAX) {
        if (data > PSW_MAX_VALUE)
            return -EINVAL;
        /* Write to psw register */
        *(addr_t *)addr = data;
    } else if (addr >= GPRS_ADDRESS_MIN && addr <= GPRS_ADDRESS_MAX) {
        if (addr % sizeof(addr_t) != 0)
            return -EINVAL;
        *(addr_t *)addr = data;
    } else if (addr >= FP_ADDRESS_MIN && addr <= FP_ADDRESS_MAX) {
        if (data > FP_MAX_VALUE)
            return -EINVAL;
        *(addr_t *)addr = data;
    } else if (addr >= PER_INFO_ADDRESS_MIN && addr <= PER_INFO_ADDRESS_MAX) {
        if (data > PER_INFO_MAX_VALUE)
            return -EINVAL;
        *(addr_t *)addr = data;
    } else {
        return -EINVAL;
    }
    return 0;
}

int write_task_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_ADDR_MIN && addr <= PSW_ADDR_MAX) {
        /* Valid psw address range, write data */
        *(addr_t *)((char *)&child->psw + (addr - PSW_ADDR_MIN)) = data;
        return 0;
    } else if (addr >= GPRS_ADDR_MIN && addr <= GPRS_ADDR_MAX) {
        /* Valid general purpose registers address range */
        if ((addr - GPRS_ADDR_MIN) % sizeof(addr_t) != 0) {
            /* Prevent writes to padding holes */
            return -EINVAL;
        }
        *(addr_t *)((char *)child->thread.gprs + (addr - GPRS_ADDR_MIN)) = data;
        return 0;
    } else if (addr >= FLOAT_REGS_ADDR_MIN && addr <= FLOAT_REGS_ADDR_MAX) {
        /* Valid floating-point registers address range */
        *(addr_t *)((char *)child->thread.float_regs + (addr - FLOAT_REGS_ADDR_MIN)) = data;
        return 0;
    } else if (addr >= PER_INFO_ADDR_MIN && addr <= PER_INFO_ADDR_MAX) {
        /* Valid per_info address range */
        *(addr_t *)((char *)&child->thread.per_info + (addr - PER_INFO_ADDR_MIN)) = data;
        return 0;
    } else {
        return -EINVAL;
    }
}
